import { ReactNode, FC } from 'react';

interface InfiniteScrollProps {
    /** 是否还有更多数据 */
    hasMore: boolean;
    /** 是否加载中 */
    loading?: boolean;
    /** 加载更多阈值 (rpx) */
    threshold?: number;
    /** 是否使用内置滚动容器 */
    scrollable?: boolean;
    /** 加载更多回调 */
    onLoadMore: () => void | Promise<void>;
    /** 加载中提示 */
    loadingText?: string;
    /** 没有更多提示 */
    finishedText?: string;
    /** 自定义加载中内容 */
    loadingContent?: ReactNode;
    /** 自定义完成内容 */
    finishedContent?: ReactNode;
    /** 子元素 */
    children?: ReactNode;
    /** 自定义类名 */
    className?: string;
}

declare const InfiniteScroll: FC<InfiniteScrollProps>;

export { InfiniteScroll, InfiniteScroll as default };
export type { InfiniteScrollProps };
